Local NumberVar plannedDays := DateDiff("d", {project.start_date}, {project.planned_end_date});
Local NumberVar taskDays := DateDiff("d", {project.start_date}, {project_task.end_date});
Local NumberVar frac;
if plannedDays <= 0 then
    frac := 0
else
    frac := taskDays / plannedDays;
if frac > 1 then 1 else if frac < 0 then 0 else frac
